// 1. Khoi chay Portkey Gateway OSS (MIT) trong mang noi bo Docker/Server:
// docker run -d --name domation-portkey-edge -p 127.0.0.1:8787:8787 portkeyai/gateway:latest

interface PortkeyRouteResponse {
  choices: Array<{ message: { content: string } }>;
  usage?: { prompt_tokens: number; completion_tokens: number; total_tokens: number };
}

export async function callEdgeRoutedLlm(systemPrompt: string, userMessage: string): Promise<string> {
  // Khai bao chien luoc fallback + exponential retry ngay trong cau hinh JSON
  const gatewayConfig = {
    strategy: {
      mode: 'fallback',
      on_status_codes: [429, 500, 502, 503, 504],
    },
    retry: {
      attempts: 3,
      on_status_codes: [429, 502, 503],
    },
    targets: [
      {
        provider: 'google',
        api_key: process.env.GEMINI_API_KEY,
        override_params: { model: 'gemini-2.5-flash', temperature: 0.2 },
      },
      {
        provider: 'anthropic',
        api_key: process.env.ANTHROPIC_API_KEY,
        override_params: { model: 'claude-haiku-4-5', max_tokens: 1024 },
      },
      {
        // Fallback cuoi cung ve cum Private vLLM trong VPC neu duong truyen Cloud gap su co
        provider: 'openai',
        custom_host: 'http://vllm-core:8000/v1',
        api_key: process.env.VLLM_INTERNAL_API_KEY,
        override_params: { model: 'domation-enterprise-32b' },
      },
    ],
  };

  const res = await fetch('http://127.0.0.1:8787/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-portkey-config': JSON.stringify(gatewayConfig),
    },
    body: JSON.stringify({
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userMessage },
      ],
    }),
  });

  if (!res.ok) {
    throw new Error(`Portkey Gateway fallback chain failed: HTTP ${res.status}`);
  }

  const data = (await res.json()) as PortkeyRouteResponse;
  return data.choices[0]?.message?.content ?? '';
}
